import java.sql.Timestamp;
import java.util.HashMap;
import java.util.Map;

public class HitRateCalculator {

    public static void main(String[] args) {
        // Create a SparkSession
        org.apache.spark.SparkConf conf = new org.apache.spark.SparkConf().setAppName("HitRateCalculator");
        org.apache.spark.api.java.JavaSparkContext sc = new org.apache.spark.api.java.JavaSparkContext(conf);
        org.apache.spark.api.java.JavaSparkContext jsc = JavaSparkContext.fromSparkContext(sc);

        // Load onsite attributed data
        JavaRDD<String> onsiteAttributedData = jsc.textFile("path/to/onsite_attributed_data.txt");
        JavaRDD<Tuple2<String, Timestamp>> onsiteAttributedDataRDD = onsiteAttributedData.map(new Function<String, Tuple2<String, Timestamp>>() {
            @Override
            public Tuple2<String, Timestamp> call(String line) throws Exception {
                String[] fields = line.split(",");
                return new Tuple2<>(fields[0], new Timestamp(Long.parseLong(fields[1])));
            }
        });

        // Load top frequent queries
        JavaRDD<String> topFrequentQueries = jsc.textFile("path/to/top_frequent_queries.txt");
        Set<String> topFrequentQueriesSet = new HashSet<>(topFrequentQueries.collect());

        // Create a map to store the query and its last access time
        Map<String, Timestamp> queryLastAccessTimeMap = new HashMap<>();

        // Process onsite attributed data
        onsiteAttributedDataRDD.foreach(new VoidFunction<Tuple2<String, Timestamp>>() {
            @Override
            public void call(Tuple2<String, Timestamp> tuple) throws Exception {
                String query = tuple._1;
                Timestamp accessTime = tuple._2;

                // Check if the query is in the top frequent queries
                if (topFrequentQueriesSet.contains(query)) {
                    // Check if it's a cache miss
                    if (!queryLastAccessTimeMap.containsKey(query) || queryLastAccessTimeMap.get(query).before(accessTime.minus(java.sql.Time.valueOf("12 hours")))) {
                        // Cache miss, update the last access time
                        queryLastAccessTimeMap.put(query, accessTime);
                        // Perform the query and cache the result
                        // ...
                    } else {
                        // Cache hit
                    }
                }
            }
        });

        // Calculate the hit rate
        long cacheMissCount = queryLastAccessTimeMap.size();
        long totalQueryCount = onsiteAttributedDataRDD.count();
        double hitRate = (totalQueryCount - cacheMissCount) * 100.0 / totalQueryCount;
        System.out.println("Hit rate: " + hitRate + "%");

        // Stop the SparkContext
        sc.stop();
    }
}
```

