We will create a custom `Tooltip` component that uses the `useContext` hook to manage the state of the tooltips. We will create a `TooltipContext` that will hold the state of the tooltips and a function to update the state.

First, let's create the `TooltipContext`:

```jsx
import React, { createContext, useState } from 'react';

export const TooltipContext = createContext();

export const TooltipProvider = ({ children }) => {
  const [tooltips, setTooltips] = useState([]);

  const addTooltip = (tooltip) => {
    setTooltips((prevTooltips) => [...prevTooltips, tooltip]);
  };

  const removeTooltip = (id) => {
    setTooltips((prevTooltips) => prevTooltips.filter((tooltip) => tooltip.id !== id));
  };

  return (
    <TooltipContext.Provider value={{ addTooltip, removeTooltip }}>
      {children}
    </TooltipContext.Provider>
  );
};
```

Now, let's create the `Tooltip` component:

```jsx
import React, { useContext, useState } from 'react';
import { TooltipContext } from './TooltipContext';

const Tooltip = ({ children, id, content }) => {
  const { addTooltip, removeTooltip } = useContext(TooltipContext);
  const [isOpen, setIsOpen] = useState(false);

  const handleMouseEnter = () => {
    addTooltip({ id, isOpen: true });
    setIsOpen(true);
  };

  const handleMouseLeave = () => {
    if (!isOpen) return;
    removeTooltip(id);
    setIsOpen(false);
  };

  return (
    <div onMouseEnter={handleMouseEnter} onMouseLeave={handleMouseLeave}>
      {children}
      {isOpen && (
        <div className="tooltip">
          <div className="tooltip-arrow" />
          <div className="tooltip-content">{content}</div>
        </div>
      )}
    </div>
  );
};

export default Tooltip;
```

