```javascript
// content.js

function takeScreenshot() {
  chrome.tabs.query({ active: true, currentWindow: true }, function (tabs) {
    chrome.tabs.sendMessage(tabs[0].id, { action: "takeScreenshot" });
  });
}

document.addEventListener("DOMContentLoaded", function () {
  const takeScreenshotButton = document.createElement("button");
  takeScreenshotButton.textContent = "Take Screenshot";
  takeScreenshotButton.addEventListener("click", takeScreenshot);
  document.body.appendChild(takeScreenshotButton);
});
```

