                            <Button onClick={open}>Add Image</Button>
                        )}
                    />
                    {imageUrl && (
                        <Button isSecondary onClick={onRemoveImage}>
                            Remove Image
                        </Button>
                    )}
                </BlockControls>
                <RichText
                    tagName="h2"
                    placeholder="Your Heading"
                    value={title}
                    onChange={onChangeTitle}
                />
                <RichText
                    tagName="p"
                    placeholder="Your Content"
                    value={content}
                    onChange={onChangeContent}
                />
                {imageUrl && <img src={imageUrl} alt={imageAlt} className="my-image" />}
            </div>
        );
    },
    save({ attributes }) {
        const { title, content, imageAlt, imageUrl } = attributes;

        return (
            <div className="my-custom-block">
                {imageUrl && <img src={imageUrl} alt={imageAlt} className="my-image" />}
                <h2>{title}</h2>
                <p>{content}</p>
            </div>
        );
    },
});
